"use client";

import * as React from "react";

import { cn } from "@/registry/luma/lib/utils";
import { AdminShell } from "@/registry/luma/blocks/admin-shell";
import { Button } from "@/registry/luma/ui/button";
import {
  Field,
  FieldContent,
  FieldDescription,
  FieldGroup,
  FieldLabel,
  FieldLegend,
  FieldSet,
} from "@/registry/luma/ui/field";
import { Input } from "@/registry/luma/ui/input";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/registry/luma/ui/select";
import { Switch } from "@/registry/luma/ui/switch";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/registry/luma/ui/tabs";

const TIMEZONE_ITEMS = [
  { value: "asia-seoul", label: "Asia/Seoul (UTC+9)" },
  { value: "utc", label: "UTC" },
  { value: "america-la", label: "America/Los_Angeles" },
] as const;

const ROLE_ITEMS = [
  { value: "admin", label: "운영자" },
  { value: "editor", label: "편집자" },
  { value: "viewer", label: "열람" },
] as const;

const ENV_ITEMS = [
  { value: "sandbox", label: "Sandbox" },
  { value: "preview", label: "Preview" },
  { value: "live", label: "Live" },
] as const;

const SECTIONS = [
  { value: "general", label: "일반" },
  { value: "members", label: "멤버·역할" },
  { value: "notifications", label: "알림" },
  { value: "security", label: "보안" },
  { value: "environment", label: "환경" },
] as const;

function SettingsPanel({
  title,
  description,
  children,
}: {
  title: string;
  description: string;
  children: React.ReactNode;
}) {
  return (
    <div
      data-slot="admin-settings-panel"
      className="min-h-0 min-w-0 rounded-[1.5rem] border border-border/70 bg-card p-4 sm:p-5"
    >
      <header className="mb-5 space-y-1">
        <h2 className="font-heading text-base font-semibold tracking-[-0.02em]">{title}</h2>
        <p className="text-sm text-muted-foreground">{description}</p>
      </header>
      {children}
    </div>
  );
}

function GeneralSection() {
  const [orgName, setOrgName] = React.useState("Luma 한국어");
  const [displayLocale, setDisplayLocale] = React.useState("ko-KR");
  const [timezone, setTimezone] = React.useState("asia-seoul");

  return (
    <SettingsPanel title="일반" description="조직 기본 정보와 표시 설정을 관리합니다.">
      <FieldGroup className="gap-5">
        <Field>
          <FieldLabel htmlFor="settings-org-name">조직명</FieldLabel>
          <Input
            id="settings-org-name"
            value={orgName}
            onChange={(event) => setOrgName(event.target.value)}
          />
          <FieldDescription>사이드바와 학습자 표면에 표시되는 이름입니다.</FieldDescription>
        </Field>
        <Field>
          <FieldLabel htmlFor="settings-locale">표시 언어</FieldLabel>
          <Input
            id="settings-locale"
            value={displayLocale}
            onChange={(event) => setDisplayLocale(event.target.value)}
          />
          <FieldDescription>운영 UI 기본 로케일입니다. 예: ko-KR</FieldDescription>
        </Field>
        <Field>
          <FieldLabel htmlFor="settings-timezone">시간대</FieldLabel>
          <Select
            items={[...TIMEZONE_ITEMS]}
            value={timezone}
            onValueChange={(value) => {
              const next = Array.isArray(value) ? value[0] : value;
              if (typeof next === "string") setTimezone(next);
            }}
          >
            <SelectTrigger id="settings-timezone" className="w-full">
              <SelectValue />
            </SelectTrigger>
            <SelectContent align="start">
              {TIMEZONE_ITEMS.map((item) => (
                <SelectItem key={item.value} value={item.value}>
                  {item.label}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </Field>
        <div className="flex justify-end pt-1">
          <Button type="button" size="sm">
            변경 사항 저장
          </Button>
        </div>
      </FieldGroup>
    </SettingsPanel>
  );
}

function MembersSection() {
  const [inviteEmail, setInviteEmail] = React.useState("");
  const [inviteRole, setInviteRole] = React.useState("editor");

  return (
    <SettingsPanel
      title="멤버·역할"
      description="운영 권한을 부여하고 초대를 보냅니다. 데모용 정적 UI입니다."
    >
      <FieldGroup className="gap-6">
        <FieldSet>
          <FieldLegend>현재 역할</FieldLegend>
          <ul className="space-y-2.5 text-sm">
            <li className="flex items-center justify-between gap-3 rounded-2xl bg-muted/50 px-3.5 py-2.5">
              <span className="font-medium">수진</span>
              <span className="text-muted-foreground">운영자</span>
            </li>
            <li className="flex items-center justify-between gap-3 rounded-2xl bg-muted/50 px-3.5 py-2.5">
              <span className="font-medium">민호</span>
              <span className="text-muted-foreground">편집자</span>
            </li>
            <li className="flex items-center justify-between gap-3 rounded-2xl bg-muted/50 px-3.5 py-2.5">
              <span className="font-medium">예린</span>
              <span className="text-muted-foreground">열람</span>
            </li>
          </ul>
        </FieldSet>

        <FieldSet>
          <FieldLegend>멤버 초대</FieldLegend>
          <FieldGroup className="gap-4">
            <Field>
              <FieldLabel htmlFor="settings-invite-email">이메일</FieldLabel>
              <Input
                id="settings-invite-email"
                type="email"
                autoComplete="email"
                placeholder="colleague@example.com"
                value={inviteEmail}
                onChange={(event) => setInviteEmail(event.target.value)}
              />
            </Field>
            <Field>
              <FieldLabel htmlFor="settings-invite-role">역할</FieldLabel>
              <Select
                items={[...ROLE_ITEMS]}
                value={inviteRole}
                onValueChange={(value) => {
                  const next = Array.isArray(value) ? value[0] : value;
                  if (typeof next === "string") setInviteRole(next);
                }}
              >
                <SelectTrigger id="settings-invite-role" className="w-full">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent align="start">
                  {ROLE_ITEMS.map((item) => (
                    <SelectItem key={item.value} value={item.value}>
                      {item.label}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </Field>
            <div className="flex justify-end">
              <Button type="button" size="sm" variant="outline">
                초대 보내기
              </Button>
            </div>
          </FieldGroup>
        </FieldSet>
      </FieldGroup>
    </SettingsPanel>
  );
}

function NotificationsSection() {
  const [publishApproval, setPublishApproval] = React.useState(true);
  const [intervention, setIntervention] = React.useState(true);
  const [weeklySummary, setWeeklySummary] = React.useState(false);

  return (
    <SettingsPanel title="알림" description="운영 이벤트에 대한 알림 수신을 설정합니다.">
      <FieldGroup className="gap-4">
        <Field orientation="horizontal">
          <Switch
            id="settings-notify-publish"
            checked={publishApproval}
            onCheckedChange={setPublishApproval}
          />
          <FieldContent>
            <FieldLabel htmlFor="settings-notify-publish">게시 승인 대기</FieldLabel>
            <FieldDescription>코스가 검토·게시 대기열에 들어오면 알립니다.</FieldDescription>
          </FieldContent>
        </Field>
        <Field orientation="horizontal">
          <Switch
            id="settings-notify-intervention"
            checked={intervention}
            onCheckedChange={setIntervention}
          />
          <FieldContent>
            <FieldLabel htmlFor="settings-notify-intervention">개입 필요</FieldLabel>
            <FieldDescription>이탈·반복 오답 등 지원이 필요한 학습자를 알립니다.</FieldDescription>
          </FieldContent>
        </Field>
        <Field orientation="horizontal">
          <Switch
            id="settings-notify-weekly"
            checked={weeklySummary}
            onCheckedChange={setWeeklySummary}
          />
          <FieldContent>
            <FieldLabel htmlFor="settings-notify-weekly">주간 요약</FieldLabel>
            <FieldDescription>매주 월요일에 운영 지표 요약을 보냅니다.</FieldDescription>
          </FieldContent>
        </Field>
        <div className="flex justify-end pt-1">
          <Button type="button" size="sm">
            변경 사항 저장
          </Button>
        </div>
      </FieldGroup>
    </SettingsPanel>
  );
}

function SecuritySection() {
  const [require2fa, setRequire2fa] = React.useState(true);
  const [shortSession, setShortSession] = React.useState(false);

  return (
    <SettingsPanel title="보안" description="계정 보호와 세션 정책을 관리합니다.">
      <FieldGroup className="gap-4">
        <Field orientation="horizontal">
          <Switch id="settings-2fa" checked={require2fa} onCheckedChange={setRequire2fa} />
          <FieldContent>
            <FieldLabel htmlFor="settings-2fa">2단계 인증 필수</FieldLabel>
            <FieldDescription>운영자·편집자 계정에 2FA를 요구합니다.</FieldDescription>
          </FieldContent>
        </Field>
        <Field orientation="horizontal">
          <Switch
            id="settings-short-session"
            checked={shortSession}
            onCheckedChange={setShortSession}
          />
          <FieldContent>
            <FieldLabel htmlFor="settings-short-session">짧은 세션</FieldLabel>
            <FieldDescription>8시간 비활성 후 다시 로그인하도록 합니다.</FieldDescription>
          </FieldContent>
        </Field>
        <div className="flex justify-end pt-1">
          <Button type="button" size="sm">
            변경 사항 저장
          </Button>
        </div>
      </FieldGroup>
    </SettingsPanel>
  );
}

function EnvironmentSection() {
  const [defaultEnv, setDefaultEnv] = React.useState("preview");

  return (
    <SettingsPanel
      title="환경"
      description="게시와 미리보기에 쓰는 기본 환경을 고릅니다. Live 승격은 별도 확인이 필요합니다."
    >
      <FieldGroup className="gap-5">
        <div className="grid grid-cols-[repeat(auto-fit,minmax(min(100%,9rem),1fr))] gap-2">
          {ENV_ITEMS.map((item) => (
            <div
              key={item.value}
              className={cn(
                "rounded-2xl border px-3.5 py-3 text-sm",
                item.value === "preview"
                  ? "border-foreground/20 bg-muted/60"
                  : "border-border/60 bg-background",
              )}
            >
              <p className="font-medium">{item.label}</p>
              <p className="mt-0.5 text-xs text-muted-foreground">
                {item.value === "sandbox"
                  ? "실험·초안"
                  : item.value === "preview"
                    ? "현재 활성"
                    : "프로덕션"}
              </p>
            </div>
          ))}
        </div>
        <Field>
          <FieldLabel htmlFor="settings-default-env">기본 게시 환경</FieldLabel>
          <Select
            items={[...ENV_ITEMS]}
            value={defaultEnv}
            onValueChange={(value) => {
              const next = Array.isArray(value) ? value[0] : value;
              if (typeof next === "string") setDefaultEnv(next);
            }}
          >
            <SelectTrigger id="settings-default-env" className="w-full">
              <SelectValue />
            </SelectTrigger>
            <SelectContent align="start">
              {ENV_ITEMS.map((item) => (
                <SelectItem key={item.value} value={item.value}>
                  {item.label}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
          <FieldDescription>
            새 코스·레슨 게시 흐름의 기본 대상입니다. Live는 원클릭으로 올리지 않습니다.
          </FieldDescription>
        </Field>
        <div className="flex justify-end pt-1">
          <Button type="button" size="sm">
            변경 사항 저장
          </Button>
        </div>
      </FieldGroup>
    </SettingsPanel>
  );
}

/**
 * Unified operator settings: vertical section tabs with organization, members, notifications, security, and environment panels.
 */
export function AdminSettings({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <AdminShell
      data-slot="admin-settings"
      activeNav="settings"
      title="설정"
      className={cn(className)}
      {...props}
    >
      <Tabs
        defaultValue="general"
        orientation="vertical"
        className="grid min-h-[32rem] w-full gap-6 @[40rem]/admin-main:grid-cols-[11rem_minmax(0,1fr)]"
      >
        <TabsList
          variant="line"
          className="h-fit w-full overflow-x-auto pb-1 @[40rem]/admin-main:w-auto @[40rem]/admin-main:flex-col @[40rem]/admin-main:items-stretch @[40rem]/admin-main:overflow-visible @[40rem]/admin-main:pb-0"
        >
          {SECTIONS.map((section) => (
            <TabsTrigger key={section.value} value={section.value} className="justify-start">
              {section.label}
            </TabsTrigger>
          ))}
        </TabsList>

        <TabsContent value="general" keepMounted className="min-w-0 outline-none">
          <GeneralSection />
        </TabsContent>
        <TabsContent value="members" keepMounted className="min-w-0 outline-none">
          <MembersSection />
        </TabsContent>
        <TabsContent value="notifications" keepMounted className="min-w-0 outline-none">
          <NotificationsSection />
        </TabsContent>
        <TabsContent value="security" keepMounted className="min-w-0 outline-none">
          <SecuritySection />
        </TabsContent>
        <TabsContent value="environment" keepMounted className="min-w-0 outline-none">
          <EnvironmentSection />
        </TabsContent>
      </Tabs>
    </AdminShell>
  );
}

export default AdminSettings;

"use client";

import * as React from "react";
import { HugeiconsIcon } from "@hugeicons/react";
import {
  Analytics01Icon,
  ArrowUpDownIcon,
  Audit01Icon,
  BookOpen01Icon,
  ComputerIcon,
  Home01Icon,
  LinkSquare02Icon,
  Logout03Icon,
  MoonIcon,
  Robot01Icon,
  Settings02Icon,
  Sun03Icon,
  UserMultipleIcon,
} from "@hugeicons/core-free-icons";

import { cn } from "@/registry/luma/lib/utils";
import {
  Breadcrumb,
  BreadcrumbItem,
  BreadcrumbLink,
  BreadcrumbList,
  BreadcrumbPage,
  BreadcrumbSeparator,
} from "@/registry/luma/ui/breadcrumb";
import { Button } from "@/registry/luma/ui/button";
import {
  DropdownMenu,
  DropdownMenuCheckboxItem,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSub,
  DropdownMenuSubContent,
  DropdownMenuSubTrigger,
  DropdownMenuTrigger,
} from "@/registry/luma/ui/dropdown-menu";
import {
  Sidebar,
  SidebarContent,
  SidebarFooter,
  SidebarGroup,
  SidebarGroupContent,
  SidebarGroupLabel,
  SidebarHeader,
  SidebarInset,
  SidebarMenu,
  SidebarMenuButton,
  SidebarMenuItem,
  SidebarProvider,
  SidebarTrigger,
  useSidebar,
} from "@/registry/luma/ui/sidebar";

export type AdminBreadcrumbItem = {
  label: string;
  href?: string;
};

export type AdminNavId =
  | "home"
  | "courses"
  | "users"
  | "analytics"
  | "settings"
  | "agents"
  | "audit";

type NavItem = {
  id: AdminNavId;
  label: string;
  icon: typeof Home01Icon;
};

type NavGroup = {
  id: string;
  label: string;
  items: NavItem[];
};

type ThemeValue = "system" | "light" | "dark";

const DEMO_PROFILE = {
  name: "수진",
  email: "sujin@luma.example",
} as const;

const THEME_OPTIONS = [
  { icon: ComputerIcon, label: "시스템", value: "system" as const },
  { icon: Sun03Icon, label: "라이트", value: "light" as const },
  { icon: MoonIcon, label: "다크", value: "dark" as const },
];

const NAV_GROUPS: NavGroup[] = [
  {
    id: "overview",
    label: "개요",
    items: [{ id: "home", label: "홈", icon: Home01Icon }],
  },
  {
    id: "content",
    label: "콘텐츠",
    items: [{ id: "courses", label: "코스", icon: BookOpen01Icon }],
  },
  {
    id: "learners",
    label: "학습자",
    items: [{ id: "users", label: "사용자", icon: UserMultipleIcon }],
  },
  {
    id: "insights",
    label: "인사이트",
    items: [{ id: "analytics", label: "분석", icon: Analytics01Icon }],
  },
  {
    id: "system",
    label: "시스템",
    items: [
      { id: "settings", label: "설정", icon: Settings02Icon },
      { id: "agents", label: "에이전트", icon: Robot01Icon },
      { id: "audit", label: "감사 로그", icon: Audit01Icon },
    ],
  },
];

function preventNav(event: React.MouseEvent | React.SyntheticEvent) {
  event.preventDefault();
}

function resolveIsDark(mode: ThemeValue) {
  if (mode === "dark") return true;
  if (mode === "light") return false;
  return window.matchMedia("(prefers-color-scheme: dark)").matches;
}

function applyThemeMode(mode: ThemeValue) {
  document.documentElement.classList.toggle("dark", resolveIsDark(mode));
}

function AdminNavGroups({ activeNav }: { activeNav: AdminNavId }) {
  const { isMobile, setOpenMobile } = useSidebar();

  return (
    <>
      {NAV_GROUPS.map((group) => (
        <SidebarGroup key={group.id}>
          <SidebarGroupLabel>{group.label}</SidebarGroupLabel>
          <SidebarGroupContent>
            <SidebarMenu>
              {group.items.map((item) => {
                const current = item.id === activeNav;
                return (
                  <SidebarMenuItem key={item.id}>
                    <SidebarMenuButton
                      isActive={current}
                      tooltip={item.label}
                      render={
                        <a
                          href={`#${item.id}`}
                          aria-label={item.label}
                          aria-current={current ? "page" : undefined}
                          onClick={(event) => {
                            preventNav(event);
                            if (isMobile) setOpenMobile(false);
                          }}
                        />
                      }
                    >
                      <HugeiconsIcon icon={item.icon} strokeWidth={2} />
                      <span>{item.label}</span>
                    </SidebarMenuButton>
                  </SidebarMenuItem>
                );
              })}
            </SidebarMenu>
          </SidebarGroupContent>
        </SidebarGroup>
      ))}
    </>
  );
}

function AdminBrand() {
  return (
    <div className="flex items-center gap-2.5 px-0.5">
      <span className="grid size-7 shrink-0 place-items-center rounded-xl bg-foreground text-[0.65rem] font-semibold text-background">
        L
      </span>
      <div className="min-w-0 flex-1">
        <p className="truncate text-sm font-semibold tracking-[-0.01em]">Luma</p>
        <p className="truncate text-[11px] text-muted-foreground">운영</p>
      </div>
    </div>
  );
}

function AdminProfileMenu() {
  const [theme, setTheme] = React.useState<ThemeValue>("system");

  React.useEffect(() => {
    if (theme !== "system") return;

    const media = window.matchMedia("(prefers-color-scheme: dark)");
    function onChange() {
      applyThemeMode("system");
    }

    media.addEventListener("change", onChange);
    return () => media.removeEventListener("change", onChange);
  }, [theme]);

  return (
    <DropdownMenu>
      <DropdownMenuTrigger
        render={
          <Button
            aria-label="프로필 메뉴"
            className="h-auto w-full justify-start gap-3 rounded-2xl px-2.5 py-2 text-start hover:bg-sidebar-accent hover:text-sidebar-accent-foreground data-popup-open:bg-sidebar-accent data-popup-open:text-sidebar-accent-foreground"
            variant="ghost"
          />
        }
      >
        <span className="min-w-0 flex-1">
          <span className="block truncate text-sm font-semibold">{DEMO_PROFILE.name}</span>
          <span className="block truncate text-xs font-normal text-muted-foreground">
            {DEMO_PROFILE.email}
          </span>
        </span>
        <HugeiconsIcon
          icon={ArrowUpDownIcon}
          strokeWidth={2}
          aria-hidden="true"
          className="size-4 shrink-0 text-muted-foreground"
        />
      </DropdownMenuTrigger>
      <DropdownMenuContent
        align="start"
        className="w-(--anchor-width) min-w-56"
        side="top"
        sideOffset={8}
      >
        <DropdownMenuGroup>
          <DropdownMenuLabel className="flex items-center gap-3 px-2.5 py-2">
            <span className="min-w-0">
              <span className="block truncate text-sm font-semibold text-popover-foreground">
                {DEMO_PROFILE.name}
              </span>
              <span className="block truncate text-xs font-normal text-muted-foreground">
                {DEMO_PROFILE.email}
              </span>
            </span>
          </DropdownMenuLabel>
        </DropdownMenuGroup>
        <DropdownMenuItem onClick={preventNav}>
          <HugeiconsIcon icon={LinkSquare02Icon} strokeWidth={2} />
          앱으로 이동
        </DropdownMenuItem>
        <DropdownMenuSub>
          <DropdownMenuSubTrigger>
            <HugeiconsIcon icon={ComputerIcon} strokeWidth={2} />
            화면 테마
          </DropdownMenuSubTrigger>
          <DropdownMenuSubContent>
            {THEME_OPTIONS.map(({ icon, label, value }) => (
              <DropdownMenuCheckboxItem
                key={value}
                checked={theme === value}
                onCheckedChange={(checked) => {
                  if (!checked) return;
                  applyThemeMode(value);
                  setTheme(value);
                }}
              >
                <HugeiconsIcon icon={icon} strokeWidth={2} aria-hidden="true" />
                {label}
              </DropdownMenuCheckboxItem>
            ))}
          </DropdownMenuSubContent>
        </DropdownMenuSub>
        <DropdownMenuItem variant="destructive">
          <HugeiconsIcon icon={Logout03Icon} strokeWidth={2} />
          어드민 로그아웃
        </DropdownMenuItem>
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

function AdminSidebar({ activeNav }: { activeNav: AdminNavId }) {
  return (
    <Sidebar className="absolute! h-full!">
      <SidebarHeader>
        <AdminBrand />
      </SidebarHeader>
      <SidebarContent>
        <AdminNavGroups activeNav={activeNav} />
      </SidebarContent>
      <SidebarFooter>
        <AdminProfileMenu />
      </SidebarFooter>
    </Sidebar>
  );
}

function AdminHeader({ title, breadcrumb }: { title: string; breadcrumb?: AdminBreadcrumbItem[] }) {
  const hasBreadcrumb = Boolean(breadcrumb?.length);

  return (
    <header
      data-slot="admin-shell-header"
      className="sticky top-0 z-20 flex h-14 shrink-0 items-center gap-2 border-b border-border/50 bg-background/90 px-3 backdrop-blur-xl @[40rem]/admin-shell:h-15 @[40rem]/admin-shell:gap-3 @[40rem]/admin-shell:px-5 @[56rem]/admin-shell:gap-4 @[56rem]/admin-shell:px-6"
    >
      <SidebarTrigger aria-label="사이드바 전환" className="shrink-0" />

      <div className="min-w-0 flex-1">
        {hasBreadcrumb ? (
          <>
            <h1 className="sr-only">{title}</h1>
            <Breadcrumb className="min-w-0">
              <BreadcrumbList className="flex-wrap gap-1 @[40rem]/admin-shell:gap-1.5">
                {breadcrumb?.map((item) => (
                  <React.Fragment key={`${item.label}-${item.href ?? "page"}`}>
                    <BreadcrumbItem className="shrink-0">
                      <BreadcrumbLink
                        href={item.href ?? "#"}
                        onClick={preventNav}
                        className="text-sm"
                      >
                        {item.label}
                      </BreadcrumbLink>
                    </BreadcrumbItem>
                    <BreadcrumbSeparator className="shrink-0" />
                  </React.Fragment>
                ))}
                <BreadcrumbItem className="min-w-0">
                  <BreadcrumbPage className="block truncate font-heading text-sm font-semibold tracking-[-0.02em] @[40rem]/admin-shell:text-base">
                    {title}
                  </BreadcrumbPage>
                </BreadcrumbItem>
              </BreadcrumbList>
            </Breadcrumb>
          </>
        ) : (
          <h1 className="truncate font-heading text-sm font-semibold tracking-[-0.02em] @[40rem]/admin-shell:text-base">
            {title}
          </h1>
        )}
      </div>
    </header>
  );
}

export function AdminShell({
  activeNav,
  title,
  breadcrumb,
  className,
  contentClassName,
  children,
  ...props
}: {
  activeNav: AdminNavId;
  title: string;
  breadcrumb?: AdminBreadcrumbItem[];
  contentClassName?: string;
  children: React.ReactNode;
} & React.ComponentProps<"div">) {
  return (
    <div
      data-slot="admin-shell"
      className={cn(
        "@container/admin-shell relative flex h-full min-h-0 w-full overflow-hidden bg-background",
        className,
      )}
      {...props}
    >
      <SidebarProvider className="relative flex h-full min-h-0! w-full flex-1 overflow-hidden">
        <AdminSidebar activeNav={activeNav} />

        <SidebarInset className="min-h-0 min-w-0 flex-1 overflow-hidden">
          <AdminHeader title={title} breadcrumb={breadcrumb} />
          <div
            data-slot="admin-shell-main"
            className={cn(
              "@container/admin-main flex min-h-0 flex-1 flex-col gap-6 overflow-auto px-3 py-5 @[40rem]/admin-shell:gap-8 @[40rem]/admin-shell:px-5 @[40rem]/admin-shell:py-7 @[56rem]/admin-shell:px-6 @[56rem]/admin-shell:py-8",
              contentClassName,
            )}
          >
            {children}
          </div>
        </SidebarInset>
      </SidebarProvider>
    </div>
  );
}
